import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"温公易说 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"温公易说 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"zh/classics/wengong/003.md","filePath":"zh/classics/wengong/003.md"}'),l={name:"zh/classics/wengong/003.md"};function n(t,a,s,d,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><h3 id="彖曰-至哉-坤元-万物资生-乃顺承天。坤厚载物-德合无疆。含光-大品物咸亨。牝马地类-行地无疆。柔顺利贞-君子攸行。先迷失道-后顺得常。西南得朋-乃与类行。东北丧朋-乃终有庆。安贞之吉-应地无疆。" tabindex="-1">彖曰：至哉，坤元！万物资生，乃顺承天。坤厚载物，德合无疆。含光，大品物咸亨。牝马地类，行地无疆。柔顺利贞，君子攸行。先迷失道，后顺得常。西南得朋，乃与类行。东北丧朋，乃终有庆。安贞之吉，应地无疆。 <a class="header-anchor" href="#彖曰-至哉-坤元-万物资生-乃顺承天。坤厚载物-德合无疆。含光-大品物咸亨。牝马地类-行地无疆。柔顺利贞-君子攸行。先迷失道-后顺得常。西南得朋-乃与类行。东北丧朋-乃终有庆。安贞之吉-应地无疆。" aria-label="Permalink to “彖曰：至哉，坤元！万物资生，乃顺承天。坤厚载物，德合无疆。含光，大品物咸亨。牝马地类，行地无疆。柔顺利贞，君子攸行。先迷失道，后顺得常。西南得朋，乃与类行。东北丧朋，乃终有庆。安贞之吉，应地无疆。”">​</a></h3><h3 id="象曰-地势坤-君子以厚德载物。" tabindex="-1">象曰：地势坤，君子以厚德载物。 <a class="header-anchor" href="#象曰-地势坤-君子以厚德载物。" aria-label="Permalink to “象曰：地势坤，君子以厚德载物。”">​</a></h3><p>干之象曰：自强不息。坤之象曰：厚德载物。何也？曰：强者，勉之谓也；载者，安济之谓也。君子自强，法天；厚德，法地。德不厚，则物不得而济也。是故，自强不息，则道无不臻；厚德而载，则物无不济。夫乾坤者，易之门户也。二象者，道德之关枢也。</p><h3 id="初六-履霜-坚冰至。-象曰-履霜-坚冰至-阴始凝也。驯致其道-至坚冰也。" tabindex="-1">初六：履霜，坚冰至。 象曰：履霜，坚冰至，阴始凝也。驯致其道，至坚冰也。 <a class="header-anchor" href="#初六-履霜-坚冰至。-象曰-履霜-坚冰至-阴始凝也。驯致其道-至坚冰也。" aria-label="Permalink to “初六：履霜，坚冰至。 象曰：履霜，坚冰至，阴始凝也。驯致其道，至坚冰也。”">​</a></h3><p>初六者，阴之始也，于律为林钟，于历为建未之月，阳气方盛，阴生而物未之知也。是故君子谨之。其曰履霜坚冰至，霜者寒之先也，冰者寒之盛也。君子见微而知彰，原始而知终，攘恶于未芽，杜祸于未萌，是以身禔而国家乂寜也。</p><h3 id="六二-直方大-不习无不利。-象曰-六二之动-直以方也。不习无不利-地道光也。" tabindex="-1">六二：直方大，不习无不利。 象曰：六二之动，直以方也。不习无不利，地道光也。 <a class="header-anchor" href="#六二-直方大-不习无不利。-象曰-六二之动-直以方也。不习无不利-地道光也。" aria-label="Permalink to “六二：直方大，不习无不利。 象曰：六二之动，直以方也。不习无不利，地道光也。”">​</a></h3><p>六二者，于律为南吕，于历为建酉之月，草木黄落，暑去而寒至也。其曰直方大何？直方而大地之徳也。六二何为擅地之徳？坤之主也。六二何为坤之主？夫阴阳虽殊，皆主中正者也。故干九五，阳之主也；坤六二，阴之主也。地之得其为直方大者何？直者言其气，方者言其形，大者兼形与气而言之也。</p><h3 id="六三-含章可贞-或从王事-无成有终。-象曰-含章可贞-以时发也。或从王事-知光大也。" tabindex="-1">六三：含章可贞，或从王事，无成有终。 象曰：含章可贞，以时发也。或从王事，知光大也。 <a class="header-anchor" href="#六三-含章可贞-或从王事-无成有终。-象曰-含章可贞-以时发也。或从王事-知光大也。" aria-label="Permalink to “六三：含章可贞，或从王事，无成有终。 象曰：含章可贞，以时发也。或从王事，知光大也。”">​</a></h3><p>乾坤之爻得位未必告失位未必凶，其故何也？曰阳非阴则不成，阴非阳则不生。阴阳之道表里相承，阴胜则消，阳胜则亢。是故乾坤以阴居阳，以阳居阴，不皆为咎也。干之九三以阳居阳而不中，故曰夕惕若厉无咎。坤之六四以阴居阴而不中，故曰括囊无咎无誉，皆刚柔太过，故须畏慎而后免咎也。然未失其正，故不凶也。九五六二居中履正，其徳最羙。九二六五不失其中，徳羙次之。九三六四不失其正，虽危无疑。九四六三虽无中正之徳，九四以阳处下，刚克而沈潜者也，故曰在渊无咎。六三以阴处上，柔克而髙明者也，故曰含章可贞。六三者，于律为应钟，于历为建亥之月，百榖敛藏，万物备成，阴功小终，体执乎柔而志存乎刚，故曰含章。柔不泥于下，刚不疑乎上，故曰可贞。王者尊之极也，为臣之荣从王役，不敢专成，下之职也，承事之终，臣之力也。物以阳生，得阴而成，令由君出，得臣而行，故阳而不阴则万物伤矣，君而不臣则百职旷矣。阴阳同功，君臣同体，天之经也，人之纪也。虞书曰：予欲左右有民，汝翼；予欲宣力四方，汝为。此之谓也。</p><h3 id="六四-括囊-无咎无誉。-象曰-括囊-无咎慎不害也。" tabindex="-1">六四：括囊，无咎无誉。 象曰：括囊，无咎慎不害也。 <a class="header-anchor" href="#六四-括囊-无咎无誉。-象曰-括囊-无咎慎不害也。" aria-label="Permalink to “六四：括囊，无咎无誉。 象曰：括囊，无咎慎不害也。”">​</a></h3><p>六四者，于律为大吕，于历为建丑之月，曰穷于次月，穷于纪天吟地闭，万物伏死，阴气大盛，阳将更始，履卑体顺，以阴居阴处，不得中而潜伏乎其深，是以幽晦否塞而不通，虽无咎亦无誉也。</p><h3 id="六五-黄裳-元吉。-象曰-黄裳-元吉-文在中也。" tabindex="-1">六五：黄裳，元吉。 象曰：黄裳，元吉，文在中也。 <a class="header-anchor" href="#六五-黄裳-元吉。-象曰-黄裳-元吉-文在中也。" aria-label="Permalink to “六五：黄裳，元吉。 象曰：黄裳，元吉，文在中也。”">​</a></h3><p>六五者，于律为夹钟，于历为建帽之月，天地始辟，和气融明，莩甲发散，庶物滋荣，体柔而志刚，乘阴而佐阳，中羙能黄，上羙则元，下羙则裳，是以吉也。</p><h3 id="上六-龙战于野-其血玄黄。-象曰-龙战于野-其道穷也。" tabindex="-1">上六：龙战于野，其血玄黄。 象曰：龙战于野，其道穷也。 <a class="header-anchor" href="#上六-龙战于野-其血玄黄。-象曰-龙战于野-其道穷也。" aria-label="Permalink to “上六：龙战于野，其血玄黄。 象曰：龙战于野，其道穷也。”">​</a></h3><p>上六者，阴之穷也，于律为仲吕，于历为建巳之月，纯阴用事，阳道已穷，冒进不已，不能守中，是以战也。夫下不能自重，重之者上也；臣不能自大，大之者君也。重而不已，上必危；大而不已，君必亏。既危且亏，能无战乎？故君子执臣之枢，守臣之机，谨其枢，固其机，祸无从来。枢机之失，儓仆为灾；虽得而胜之，犹有伤也。故曰其血黄。文言曰：臣弒其君，子弒其父，非一朝一夕之故，其所由来者渐矣，由辨之不早辨也。呜呼，圣人之戒为人上者如此其深乎！</p><h3 id="用六-利永贞。-象曰-用六-永贞以大终也。" tabindex="-1">用六：利永贞。 象曰：用六，永贞以大终也。 <a class="header-anchor" href="#用六-利永贞。-象曰-用六-永贞以大终也。" aria-label="Permalink to “用六：利永贞。 象曰：用六，永贞以大终也。”">​</a></h3><p>文言曰：</p><h3 id="坤至柔而动也刚-至静而德方。后得主而有常-含万物而化光。坤道其顺乎-承天而时行。积善之家-必有余庆-积不善之家-必有余殃。臣弑其君-子弑其父-非一朝一夕之故-其所由来者渐矣。由辨之不早辨也。《易》曰-履霜坚冰至-盖言顺也。直其正也-方其义也。君子敬以直内-义以方外。敬义立而德不孤-直方大不习-无不利-则不疑其所行也。" tabindex="-1">坤至柔而动也刚，至静而德方。后得主而有常，含万物而化光。坤道其顺乎？承天而时行。积善之家，必有余庆；积不善之家，必有余殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣。由辨之不早辨也。《易》曰：履霜坚冰至，盖言顺也。直其正也，方其义也。君子敬以直内，义以方外。敬义立而德不孤，直方大不习，无不利，则不疑其所行也。 <a class="header-anchor" href="#坤至柔而动也刚-至静而德方。后得主而有常-含万物而化光。坤道其顺乎-承天而时行。积善之家-必有余庆-积不善之家-必有余殃。臣弑其君-子弑其父-非一朝一夕之故-其所由来者渐矣。由辨之不早辨也。《易》曰-履霜坚冰至-盖言顺也。直其正也-方其义也。君子敬以直内-义以方外。敬义立而德不孤-直方大不习-无不利-则不疑其所行也。" aria-label="Permalink to “坤至柔而动也刚，至静而德方。后得主而有常，含万物而化光。坤道其顺乎？承天而时行。积善之家，必有余庆；积不善之家，必有余殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣。由辨之不早辨也。《易》曰：履霜坚冰至，盖言顺也。直其正也，方其义也。君子敬以直内，义以方外。敬义立而德不孤，直方大不习，无不利，则不疑其所行也。”">​</a></h3><p>注释：君子法地之直方，则敬以直内，义以方外。敬义立而德不孤，则大也。何谓敬以直内，义以方外？敬则所受不陷于败也，义则所适不失其宜也。直且方者，守诸己而无待于外也。君子居则不陷于败，动则不爽其宜。施于身而身正，施于国而国治。夫又何习而何不利焉，可以断然无疑矣。</p><h3 id="阴虽有美-含之以从王事-弗敢成也。地道也-妻道也-臣道也。地道无成而代有终也。天地变化-草木蕃-天地闭-贤人隐。《易》曰-括囊无咎无誉-盖言谨也。君子黄中通理-正位居体-美在其中而畅于四肢-发于事业-美之至也。阴疑于阳-必战-为其嫌于无阳也-故称龙焉。犹未离其类也-故称血焉。夫黄者-天地之杂也-天而地黄。" tabindex="-1">阴虽有美，含之以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成而代有终也。天地变化，草木蕃；天地闭，贤人隐。《易》曰：括囊无咎无誉，盖言谨也。君子黄中通理，正位居体，美在其中而畅于四肢，发于事业，美之至也。阴疑于阳，必战，为其嫌于无阳也，故称龙焉。犹未离其类也，故称血焉。夫黄者，天地之杂也，天而地黄。 <a class="header-anchor" href="#阴虽有美-含之以从王事-弗敢成也。地道也-妻道也-臣道也。地道无成而代有终也。天地变化-草木蕃-天地闭-贤人隐。《易》曰-括囊无咎无誉-盖言谨也。君子黄中通理-正位居体-美在其中而畅于四肢-发于事业-美之至也。阴疑于阳-必战-为其嫌于无阳也-故称龙焉。犹未离其类也-故称血焉。夫黄者-天地之杂也-天而地黄。" aria-label="Permalink to “阴虽有美，含之以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成而代有终也。天地变化，草木蕃；天地闭，贤人隐。《易》曰：括囊无咎无誉，盖言谨也。君子黄中通理，正位居体，美在其中而畅于四肢，发于事业，美之至也。阴疑于阳，必战，为其嫌于无阳也，故称龙焉。犹未离其类也，故称血焉。夫黄者，天地之杂也，天而地黄。”">​</a></h3>',21)])])}const _=e(l,[["render",n]]);export{b as __pageData,_ as default};
